def main() -> None:
    # --- docs/README.md: rebuild the secondary task table ---
    text = mdpatch.read(DOCS)
    lines = text.split(NL)
    head = [i for i, line in enumerate(lines) if line.startswith(HEADER)]
    if len(head) != 1:
        raise SystemExit("update_docs_index: header anchor count %d" % len(head))
    start = head[0]
    tail = [i for i, line in enumerate(lines)
            if i > start and line.startswith("## ")]
    if not tail:
        raise SystemExit("update_docs_index: end anchor not found")
    end = tail[0]
    rows = ROWS_TEXT.split(NL)
    while rows and rows[-1] == "":
        rows.pop()
    lines[start:end] = rows + [""]
    text = NL.join(lines)
    text = mdpatch.insert_before(
        text,
        "| 序 | 任务 | 标题 |",
        "",
        "table-note",
    )
    mdpatch.write(DOCS, text)

    # --- runtime_evidence/README.md: append this round's index ---
    ev = mdpatch.read(EVID)
    if not ev.endswith(NL):
        ev = ev + NL
    ev = ev + EV_TEXT
    mdpatch.write(EVID, ev)
    print("update_docs_index: ok")


if __name__ == "__main__":
    main()

